-- Nihongo Labs kanji decks: exact N5 and N4 lists supplied by the product owner.
-- The product owner confirms N4 readings and example vocabulary have been reviewed by a Japanese editor.
-- JLPT does not publish fixed official kanji inventories per level; these are Nihongo Labs curriculum decks.
begin;

create table if not exists public.kanji_review_state (
  user_id uuid not null references auth.users(id) on delete cascade,
  kanji_id uuid not null references public.kanji_entries(id) on delete cascade,
  status text not null default 'new' check (status in ('new', 'learning', 'known')),
  repetitions integer not null default 0 check (repetitions >= 0),
  interval_days integer not null default 0 check (interval_days >= 0),
  due_at timestamptz not null default now(),
  last_reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, kanji_id)
);

create index if not exists kanji_review_due_idx
  on public.kanji_review_state(user_id, due_at);

alter table public.kanji_review_state enable row level security;
drop policy if exists kanji_review_state_owner on public.kanji_review_state;
create policy kanji_review_state_owner
  on public.kanji_review_state
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

grant select, insert, update, delete on public.kanji_review_state to authenticated;

on conflict(jlpt_level,character) do update set
 meaning=excluded.meaning,
 on_yomi=excluded.on_yomi,
 kun_yomi=excluded.kun_yomi,
 stroke_count=excluded.stroke_count,
 radical=excluded.radical,
 mnemonic=excluded.mnemonic,
 example_words=excluded.example_words,
 publication_status='published',
 updated_at=now();

on conflict(jlpt_level,character) do update set
 meaning=excluded.meaning,
 on_yomi=excluded.on_yomi,
 kun_yomi=excluded.kun_yomi,
 stroke_count=excluded.stroke_count,
 radical=excluded.radical,
 mnemonic=excluded.mnemonic,
 example_words=excluded.example_words,
 publication_status='published',
 updated_at=now();

commit;
